@php
use Carbon\Carbon;
use App\Models\AccountOfficer;

Carbon::setLocale('id');

// tanggal dokumen (tanpa jam)
$tanggal = Carbon::now('Asia/Jakarta')->startOfDay();
$hari = $tanggal->translatedFormat('l');
$tanggalText = $tanggal->translatedFormat('d F Y');

// contoh jatuh tempo (+1 bulan dari tanggal dokumen)
$jatuhTempoText = $tanggal->copy()->addMonth()->translatedFormat('d F Y');

// sumber data kredit: simulation (kalau ada), fallback ke debitur
$sim = $simulation ?? ($debitur->simulation ?? null);

// mapping field debitur/simulation
$namaDebitur   = $sim->nama ?? ($debitur->nama ?? '');
$alamatDebitur = $sim->alamat ?? ($debitur->alamat ?? '');
$noRek         = $sim->no_rek ?? ($sim->no_rekening ?? ($debitur->no_rek ?? ''));

$plafond = $sim->plafond ?? ($debitur->jumlah_permohonan_kredit ?? 0);
$jangkaWaktu = $sim->jangka_waktu ?? ($debitur->jangka_waktu ?? '');
$bunga = $sim->bunga_flat ?? ($debitur->bunga_flat ?? '');
$angsuran = $sim->angsuran ?? '';

// mapping sisi kanan (jika ada di simulations)
$collectibility = $sim->collectibility ?? '';
$golDebitur     = $sim->gol_debitur ?? '';
$sektorEkonomi  = $sim->sektor_ekonomi ?? '';
$lokasi         = $sim->lokasi ?? '';

// mapping nominal (jika ada di simulations)
$nominal_tab_duta     = 'Rp ' . number_format((float)($sim->tab_duta ?? 0), 0, ',', '.');
$nominal_pend_adm     = 'Rp ' . number_format((float)($sim->pend_adm_krd ?? $sim->biaya_administrasi ?? 0), 0, ',', '.');
$nominal_pend_provisi = 'Rp ' . number_format((float)($sim->pend_provisi ?? $sim->provisi ?? 0), 0, ',', '.');
$nominal_materai      = 'Rp ' . number_format((float)($sim->biaya_materai ?? 0), 0, ',', '.');
$nominal_asuransi     = 'Rp ' . number_format((float)($sim->biaya_asuransi ?? 0), 0, ',', '.');

// terbilang plafond (pakai helper formatRupiah/terbilang yang sudah ada di project; fallback sederhana)
if (function_exists('formatRupiah')) {
    $terbilangPlafond = formatRupiah((string)$plafond);
} else {
    $terbilangPlafond = number_format((float)$plafond, 0, ',', '.');
}

// Account Officer & pejabat (ambil dari tabel account_officer)
$aoNama = AccountOfficer::where('nama_dokumen', 'MEMORANDUM DROPPING PENCAIRAN KREDIT')
            ->where('jabatan', 'AO')->value('nama')
         ?? optional($debitur->accountOfficer)->nama
         ?? '';
$peBisnisNama = AccountOfficer::where('nama_dokumen', 'MEMORANDUM DROPPING PENCAIRAN KREDIT')
            ->where('jabatan', 'PE BISNIS')->value('nama')
         ?? 'FITRA RAMDANI';
$direkturNama = AccountOfficer::where('nama_dokumen', 'MEMORANDUM DROPPING PENCAIRAN KREDIT')
            ->where('jabatan', 'DIREKTUR UTAMA')->value('nama')
         ?? 'INDRIANTI SUKARMADIJAYA';
@endphp

